$('#modelSettings').onclick=()=>{$('#endpoint').value=localStorage.getItem('ft-endpoint')||'';$('#model').value=localStorage.getItem('ft-model')||'gemma4:e2b';$('#settingsDialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#howItWorks').onclick=()=>$('#aboutDialog').showModal();$('#connect').onclick=()=>{try{const u=new URL($('#endpoint').value.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error('Use an HTTP(S) endpoint without credentials or query parameters.');const model=$('#model').value.trim();if(!model)throw Error('Enter your installed model name.');localStorage.setItem('ft-endpoint',u.href.replace(/\/$/,''));localStorage.setItem('ft-model',model);setConnectionLabel();$('#settingsDialog').close();status('Endpoint saved, not yet tested. Submit a question to request a live Gemma plan.')}catch(e){$('#settingsStatus').textContent=e.message}};$('#disconnect').onclick=()=>{localStorage.removeItem('ft-endpoint');setConnectionLabel();$('#settingsDialog').close();status('Model disconnected. Curated experiments remain available.')};

function classify(q){const s=q.toLowerCase();if(/singular|conservative|counterexample|loophole|hole/.test(s))return'singular';if(/gradient|potential|steep|uphill/.test(s))return'gradient';if(/saddle|stretch|compress/.test(s))return'saddle';if(/source|sink|expand|divergence theorem/.test(s))return'source';return'vortex'}
async function submitQuestion(q){$('#question').value=q;const scope=scopeGate(q);if(scope.decision!=='allow'){request++;$('#modeBadge').textContent=scope.decision==='blocked'?'CODE SCOPE CHECK · UNSUPPORTED · NO AI CALL':'CODE SCOPE CHECK · CLARIFICATION · NO AI CALL';status(scope.message);return}let explicit;try{explicit=extractExplicitField(q)}catch(error){status('Formula not applied: '+error.message+' Enter three scalar components.');return}if(explicit){const candidate=compileField(explicit);const token=++request;$('#planText').textContent='EXPLICIT FORMULA · READ DIRECTLY, NO MODEL REWRITE\nField: ⟨'+candidate.expressions.join(', ')+'⟩\nBoundary: circle in z = 0, radius 1.5. Surface lift: 0. Parameter a: 1.\nConfirm the extracted components match your input. For a language-based Gemma plan, describe the behavior instead of entering a formula.';$('#planDialog').showModal();const accepted=await new Promise(resolve=>{pendingPlan=resolve});if(!accepted||request!==token)return;choose('vortex');field=candidate;custom=true;$('#fieldTitle').textContent='Your formula, preserved.';$('#fieldTag').textContent='DIRECT FORMULA · NO MODEL REWRITE';$('#sceneLabel').textContent='YOUR CARTESIAN FIELD';$('#equation').textContent='F = ⟨'+candidate.expressions.join(', ')+'⟩';$('#modeBadge').textContent='DIRECT PARSER · COMPUTED MATH · NO AI CALL';recalculate();rebuild();renderNotes();status('Formula read directly and calculated. No model call was made. Explore for me runs the comparisons.');return}const endpoint=localStorage.getItem('ft-endpoint');if(!endpoint){choose(classify(q));$('#modeBadge').textContent='KEYWORD MATCH · CURATED EXAMPLE · NO AI CALL';status('No model connected. Selected a keyword-matched example; unsupported requests are not assessed by this fallback. Connect Gemma for bounded planning.');return}const token=++request;$('#generate').disabled=true;status('Gemma is selecting a supported field and comparison…');try{const response=await fetch(endpoint+'/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:localStorage.getItem('ft-model'),stream:false,format:plannerSchema,options:{temperature:0,num_predict:100},prompt:plannerPrompt(q)}),signal:AbortSignal.timeout(90000)});if(!response.ok)throw Error('Model endpoint returned '+response.status);const data=await response.json();const plan=validatePlan(JSON.parse(data.response));if(request!==token)return;if(plan.field==='outside_scope'){status('Gemma marked this request outside the five supported experiments. The current field is unchanged. Try rotation, expansion, saddle deformation, a gradient example, or the excluded-axis counterexample.');$('#modeBadge').textContent='GEMMA PLAN · OUTSIDE SCOPE';return}const plannedField=compileField(PRESETS[plan.field].field);$('#planText').textContent='GEMMA SELECTED: '+PRESETS[plan.field].name+'\nCOMPARISON: '+plan.comparison+'\nField supplied by code: ⟨'+plannedField.expressions.join(', ')+'⟩\nDefaults: a = 1, radius = 1.5, lift = 0. The boundary is a circle in z = 0.\nCheck that this supported example matches your question. Gemma selects IDs; it does not generate these formulas.';$('#planDialog').showModal();const accepted=await new Promise(resolve=>{pendingPlan=resolve});if(!accepted||request!==token){status('Plan not applied. Your experiment is unchanged.');return}choose(plan.field);explanation='GEMMA PLAN · '+PRESETS[plan.field].name+' · '+plan.comparison+' comparison. Formulas and observations below are supplied by code.\n'+PRESETS[plan.field].description;renderNotes();$('#modeBadge').textContent='GEMMA-SELECTED EXPERIMENT · CODE-SUPPLIED FORMULA';if(plan.comparison!=='none')runInvestigation(plan.comparison);status('Gemma selected '+PRESETS[plan.field].name+' / '+plan.comparison+'. Code supplied the field and calculated the results.');}catch(error){if(request===token)status('Gemma planner failed: '+error.message+' Your experiment is unchanged.')}finally{$('#generate').disabled=false}}

$('#askForm').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q)submitQuestion(q)};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>submitQuestion(b.dataset.question));
function snapshot(){return{investigation,version:1,key,custom,expressions:field.expressions,...parameters(),question:$('#question').value,explanation,createdAt:new Date().toISOString(),math:{divergence:field.divText,curl:field.curlText,...result},scope:'Cartesian field; circular boundary in z=0; parabolic spanning surface. Numerical agreement is not proof.'}}
$('#saveWorkspace').onclick=()=>{localStorage.setItem('ft-workspace',JSON.stringify(snapshot()));status('Workspace saved in this browser. Restore it from “How this lab works”.')};$('#restoreWorkspace').onclick=()=>{try{const s=validateWorkspace(JSON.parse(localStorage.getItem('ft-workspace')));if(!s||s.version!==1||!Object.hasOwn(PRESETS,s.key))throw Error('No compatible saved workspace.');choose(s.key,{strength:s.a,radius:s.radius,lift:s.lift});orientation=s.orientation===-1?-1:1;if(s.custom){field=compileField(s.expressions);custom=true;$('#equation').textContent='F = ⟨'+field.expressions.join(', ')+'⟩';$('#fieldTitle').textContent='Your saved custom field.';$('#fieldTag').textContent='CUSTOM FIELD';}$('#question').value=s.question||'';explanation='';updateControls();recalculate();rebuild();renderNotes();$('#aboutDialog').close();status('Saved workspace restored.')}catch(e){status(e.message);$('#aboutDialog').close()}};
$('#saveLesson').onclick=()=>{const s=snapshot(),p=PRESETS[key];const text=`# FieldTrip — ${custom?'Custom field':p.name}\n\nQuestion: ${s.question||'Preset exploration'}\n\nField: <${field.expressions.join(', ')}>\nStrength parameter a (only affects formulas containing a): ${a}; loop radius R: ${radius}; surface lift h: ${lift}; orientation: ${orientation}\n\nDivergence: ${field.divText}\nCurl: <${field.curlText.join(', ')}>\n\nBoundary circulation ≈ ${result.line}\nCurl flux through surface ≈ ${result.flux}\nAbsolute difference: ${result.residual}\n\n${s.scope}\n\n${custom?'User-defined field.':p.description}\n\n${custom?'Review domain and smoothness.':p.note}\n\n${explanation?'Selected checked observations: '+explanation:'No live model explanation in this lesson.'}\n\nVisualization: particle trajectories illustrate flow, not density-based divergence. Numerical RK4 integration and midpoint quadrature.\n\n## Reproducible workspace\n\n\`\`\`json\n${JSON.stringify(s,null,2)}\n\`\`\`\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'})),link=document.createElement('a');link.href=url;link.download='fieldtrip-lesson.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Lesson exported with equations, parameters, calculations and limitations.')};
setConnectionLabel();choose('vortex');requestAnimationFrame(animate);

$('#acceptPlan').onclick=()=>{const resolve=pendingPlan;pendingPlan=null;$('#planDialog').close();resolve?.(true)};
$('#planDialog').addEventListener('close',()=>{if(pendingPlan){const resolve=pendingPlan;pendingPlan=null;resolve(false)}});
function downloadFile(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function runInvestigation(comparison='all'){investigation={field:[...field.expressions],createdAt:new Date().toISOString(),base:parameters(),comparison,rows:selectComparisons(investigate(field,parameters()),comparison)};const panel=$('#investigation');panel.hidden=false;panel.innerHTML='<div class="eyebrow">COMPARISONS CALCULATED BY CODE</div><h2>Less setup. More evidence.</h2><p>The current field and parameter a stay fixed. Click a row to replay its configuration.</p><div class="comparison-scroll"><table><thead><tr><th>Experiment</th><th>Circulation</th><th>Curl flux</th><th>Difference</th></tr></thead><tbody>'+investigation.rows.map((row,i)=>'<tr><td><button data-replay="'+i+'">'+'Replay: '+esc(row.label)+' ↗</button></td><td>'+row.line.toFixed(4)+'</td><td>'+row.flux.toFixed(4)+'</td><td>'+row.residual.toExponential(1)+(row.invalid?' · undefined samples':'')+'</td></tr>').join('')+'</tbody></table></div><p>'+esc(observationCatalog(field,parameters(),result).domain)+'</p><p>These are numerical comparisons, not a proof or new mathematical discovery.</p>';panel.querySelectorAll('[data-replay]').forEach(button=>button.onclick=()=>{const row=investigation.rows[Number(button.dataset.replay)];({a,radius,lift,orientation}=row.parameters);for(const id of ['strength','radius','lift'])$('#'+id).value=id==='strength'?a:id==='radius'?radius:lift;explanation='';request++;recalculate();updateGeometry();renderNotes();status('Replaying '+row.label+'. The table retains the original investigation settings.');});status(investigation.rows.length+' comparisons calculated. Review or replay each result, then export the investigation.');panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
$('#exploreForMe').onclick=()=>runInvestigation('all');
$('#exportInvestigation').onclick=()=>downloadFile('fieldtrip-investigation.json',JSON.stringify(snapshot(),null,2),'application/json');
$('#importInvestigation').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>200000)throw Error('Workspace file is too large.');const s=validateWorkspace(JSON.parse(await file.text()));choose(s.key,{strength:s.a,radius:s.radius,lift:s.lift});field=compileField(s.expressions);custom=true;orientation=s.orientation;$('#question').value=typeof s.question==='string'?s.question.slice(0,2000):'';$('#equation').textContent='F = ⟨'+field.expressions.join(', ')+'⟩';$('#fieldTitle').textContent='Imported investigation';$('#fieldTag').textContent='IMPORTED · RECALCULATED';$('#modeBadge').textContent='IMPORTED EXPRESSIONS · COMPUTED MATH';recalculate();rebuild();renderNotes();status('Workspace imported. All current results were recalculated; saved claims and numbers were not trusted. Click Explore for me to regenerate comparisons.')}catch(error){status('Import failed: '+error.message)}finally{event.target.value=''}};
